WITH with_windows AS (SELECT id, store_id, product_id, last_restock, LEAD(quantity, 1) OVER (PARTITION BY store_id ORDER BY quantity, id) AS next_quantity, LAG(quantity, 1, 0) OVER (ORDER BY last_restock, id) AS prev_quantity FROM inventory WHERE product_id = 6) SELECT CASE WHEN prev_quantity >= 247 THEN 'HIGH' ELSE 'LOW' END AS prev_quantity_tier, PERCENTILE_APPROX(next_quantity, ARRAY(0.25, 0.5, 0.75)) AS next_quantity_quartiles, COUNT(DISTINCT product_id) AS distinct_product_ids, MAX(prev_quantity) AS max_prev_quantity, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS event_count FROM with_windows GROUP BY CASE WHEN prev_quantity >= 247 THEN 'HIGH' ELSE 'LOW' END
